<?php require __DIR__.'/inc/page_helpers.php';$q=$db->prepare("SELECT g.*,u.username FROM games g LEFT JOIN users u ON u.id=g.creator_id WHERE g.id=? AND g.status='active'");$q->execute([(int)($_GET['id']??0)]);$game=$q->fetch();if($game)$db->prepare('UPDATE games SET visits=visits+1 WHERE id=?')->execute([$game['id']]);page_start($game?$game['title']:'Place not found');?><section class="Panel"><?php if(!$game):?><h1>Place not found</h1><?php else:?><h1><?=e($game['title'])?></h1><p><?=nl2br(e($game['description']))?></p><p>Creator: <?=e($game['username']??'Player')?> · Visits: <?=(int)$game['visits']+1?></p><?php if(!empty($game['launch_url'])&&filter_var($game['launch_url'],FILTER_VALIDATE_URL)&&parse_url($game['launch_url'],PHP_URL_SCHEME)==='https'):?><p><a class="Button" href="<?=e($game['launch_url'])?>" target="_blank" rel="noopener noreferrer">Play this place</a></p><?php else:?><p class="notice">This place has no browser-playable URL configured. Legacy Roblox client integration is still pending.</p><?php endif;?><form method="post" action="/Report.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="game"><input type="hidden" name="id" value="<?=(int)$game['id']?>"><label>Report reason<input name="reason" maxlength="1000" required></label><button>Report place</button></form><?php endif;?></section><?php page_end();?>